scripts/migrations/data_20260827194239_2026-08-27-rename-execution.sql:20:INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0173', 'D-METH', 'DG-NON', 'Owner ruling. The pipeline shape, the project vocabulary and the research methodology are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable.', 'The concept vocabulary is harvested at evidence and adjudicated at judgment. DR-2026-08-24 §2.4 deferral to synthesis is OVERRULED.', 'ADOPTED by owner ruling 2026-08-27: "overrule Aug 24 DR. we go evidence>judgment>synthesis."', 'The owner posed the aporia: "we do not want to presuppose categories/concepts/approaches/elements/techniques/practices by defining them all at the start of the project. however, we also can''t perform our research properly if we don''t presuppose all of those." It is a false dilemma. The vocabulary need not be stipulated or absent; it can be observed but not yet adjudicated. Recording that a source uses a phrase is a fact about the document, not a claim that the phrase names one of our categories -- the same epistemic act as recording its DOI. Judgment then adjudicates with the source in hand, and the vocabulary is grown with warrant. The seed problem is answered by ratified doctrine rather than a new decision: pipeline-map.yaml:78 (2026-08-21) establishes that these are layers a walk re-enters. Measured: most of the mechanism exists -- evidence_sources carries 30 APA-shaped columns including _en variants, and terms (88) plus term_aliases (2,382) plus term_item_links (147) are the canonical layer. Missing is the harvest; nothing holds terms as they appear in a source, and search_executions.terms_used is the opposite direction.', '2026-08-27 13:52', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-27-concept-vocabulary-harvested-at-evidence-adjudicated-at-judgment.md", "references/project-standards.md (entries dated 2026-08-27)", "references/owner-notes/2026-08-27-architecture-note.md"]', '["Keep the \u00a72.4 deferral to synthesis -- overruled by the owner; judgment holds the source and synthesis does not, so judgment serves the DR''s own purpose better.", "Stipulate the vocabulary up front -- rejected by the owner as the presupposition the aporia warns against."]', 'Scoped to §2.4. §2.1 (rule 5, "point, do not copy") is untouched and remains operative; the R2 audit found this scoping "defensible and compelled, not protective narrowing", by reductio -- the whole-DR reading would strike §R8, which the owner re-affirmed the same day. Sweep owed: CLAUDE.md §6 states "applicability is an OUTPUT of synthesis" and "zero item_population_links is the correct pre-synthesis state", both superseded; D-0165 moves upstream; research_batch_dod R4 measures the wrong stage.', '2026-08-27 13:52', 'session_2026-08-27-rename-execution', '2026-08-27 13:52', 'session_2026-08-27-rename-execution');
